// A mirror ball in a panorama. iTexture0 is an equirectangular photo: a full 360° view with
// the direction around across it and the height up it. Each pixel casts a ray from a camera
// circling the ball. Rays that miss show the panorama; rays that hit the ball bounce off it
// and show the panorama in reflection. iFloat0 on the timeline zooms the camera.
#define zoom iFloat0
#define PI 3.14159265

// The colour of the panorama seen in direction dir.
vec3 panorama(vec3 dir) {
  float around = atan(dir.z, dir.x) / (2.0 * PI) + 0.5;
  float up = asin(clamp(dir.y, -1.0, 1.0)) / PI + 0.5;
  vec2 uv = vec2(around, up);
  // Where the photo's left and right edges meet, "around" jumps from 1 back to 0. Texture
  // lookups take that jump as the picture being squashed, and blur a line of pixels. Giving
  // the lookup how fast uv changes between pixels, without the jump, avoids the seam.
  vec2 dx = dFdx(uv);
  vec2 dy = dFdy(uv);
  dx.x -= round(dx.x);
  dy.x -= round(dy.x);
  return textureGrad(iTexture0, uv, dx, dy).rgb;
}

// How far along the ray from origin in direction dir it hits a ball of the given radius at
// the centre of the scene, or -1 if it misses.
float hitBall(vec3 origin, vec3 dir, float radius) {
  float b = dot(origin, dir);
  float h = b * b - dot(origin, origin) + radius * radius;
  return h < 0.0 ? -1.0 : -b - sqrt(h);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // A camera circling the ball and looking at it, bobbing up and down.
  float angle = 0.35 * iTime;
  vec3 camera = vec3(3.0 * sin(angle), 0.8 * sin(0.4 * iTime), 3.0 * cos(angle));
  vec3 forward = normalize(-camera);
  vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(right, forward);

  // The ray through this pixel. A bigger zoom narrows the view.
  vec3 ray = normalize(zoom * forward + uv.x * right + uv.y * up);

  vec3 col = panorama(ray);
  float t = hitBall(camera, ray, 1.0);
  if (t > 0.0) {
    vec3 normal = normalize(camera + t * ray);
    // Mirrors reflect more at grazing angles (the Fresnel effect).
    float fresnel = 0.6 + 0.4 * pow(1.0 - max(dot(-ray, normal), 0.0), 3.0);
    col = fresnel * panorama(reflect(ray, normal)) * vec3(1.0, 0.95, 0.9);
  }
  fragColor = vec4(col, 1.0);
}
